using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Application.Abstractions;using OrcaFacil.Application.Plans;using OrcaFacil.Domain.Entities;using OrcaFacil.Domain.Plans;using OrcaFacil.Persistence;using OrcaFacil.Web.Extensions;
namespace OrcaFacil.Web.Pages.Settings;[Authorize]public sealed class AuditModel(OrcaFacilDbContext db,ICurrentAccountService current,IPlanAccessService plans):PageModel{public IReadOnlyList<AuditLog> Events{get;private set;}=[];public async Task<IActionResult> OnGetAsync(CancellationToken ct){if(!current.AccountId.HasValue)return Forbid();var decision=await plans.CanUseAsync(current.AccountId.Value,PlanFeatureCodes.AccountAuditEnabled,ct);if(!decision.IsAllowed){TempData.Warning("A auditoria da conta está disponível a partir do plano Negócio. Conheça os planos.");return RedirectToPage("/Subscription/Index");}Events=await db.AuditLogs.AsNoTracking().Where(x=>x.AccountId==current.AccountId&&!x.IsDeleted).OrderByDescending(x=>x.CreatedAt).Take(200).ToListAsync(ct);return Page();}}
